def transform(grid):
    """Shift the whole grid down by one row, filling the top row with background."""
    if not grid:
        return []
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    return [[background] * len(grid[0])] + [row[:] for row in grid[:-1]]
